arguments.content:
// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount, applied after the
// customer's discount.
// Rounding: a total with a customer discount drops the fraction below one yen.
// A total without one (discount 0) keeps rounding half a yen up, because wholesale
// invoices use it as the amount on the printed price list (see invoice.js).
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  const discounted = subtotal * (1 - discount) * (1 - bulk);
  return discount > 0 ? dropFraction(discounted) : Math.round(discounted);
}

// Math.floor alone would lose a yen when floating point lands just below a whole
// amount (2,150 * 0.94 gives 2020.9999999999998), so an amount within a millionth
// of a whole yen counts as that whole yen.
function dropFraction(amount) {
  const nearest = Math.round(amount);
  return Math.abs(amount - nearest) < 1e-6 ? nearest : Math.floor(amount);
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

